using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using VirgilPatch;
class InstallationTests {
 static string root;static int passed;
 static void Assert(bool b,string why){if(!b)throw new Exception(why);}
 static void Test(string n,Action f){f();passed++;Console.WriteLine("PASS "+n);}
 static State Seed(bool valid=true){string area=Path.Combine(root,Guid.NewGuid().ToString("N"));Config.StateDir=Path.Combine(area,"state");string main=Path.Combine(area,"Epsilon");string retail=Path.Combine(main,"_retail_");Directory.CreateDirectory(Path.Combine(main,"Data"));Directory.CreateDirectory(Path.Combine(retail,"Patches"));if(valid)File.WriteAllText(Path.Combine(main,"Epsilon.exe"),"fixture");File.WriteAllText(Path.Combine(retail,"Wow.exe"),"fixture");File.WriteAllText(Path.Combine(retail,"EpsilonAddon.dll"),"fixture");var s=new State{patches_dir=Path.Combine(retail,"Patches")};s.Save();return s;}
 static object Field(MainForm f,string n){return typeof(MainForm).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);}
 static void Check(MainForm f){typeof(MainForm).GetMethod("RunPatchCheck",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{true,true});}
 static void Pump(Func<bool> ready){var end=DateTime.UtcNow.AddSeconds(10);while(!ready()){if(DateTime.UtcNow>end)throw new Exception("Timeout");Application.DoEvents();Thread.Sleep(10);}Application.DoEvents();}
 [STAThread]static int Main(string[] args){try{root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Application.EnableVisualStyles();Config.StartAmbienceMuted=true;
 Test("valid-main-retail-and-patches-markers-pass",delegate{var s=Seed();Assert(InstallationFolders.Inspect(s.patches_dir).Valid,"Valid layout rejected");});
 Test("missing-main-epsilon-executable-is-rejected",delegate{var s=Seed(false);Assert(!InstallationFolders.Inspect(s.patches_dir).Valid,"Wrong main accepted");});
 Test("missing-retail-addon-and-wow-are-rejected",delegate{var s=Seed();File.Delete(Path.Combine(Path.GetDirectoryName(s.patches_dir),"EpsilonAddon.dll"));Assert(!InstallationFolders.Inspect(s.patches_dir).Valid,"Generic WoW accepted");File.Delete(Path.Combine(Path.GetDirectoryName(s.patches_dir),"Wow.exe"));Assert(!InstallationFolders.Inspect(s.patches_dir).Valid,"Missing Wow accepted");});
 Test("patch-subfolder-cannot-be-treated-as-patches-root",delegate{var s=Seed();Directory.CreateDirectory(Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(4.0.0)"));Assert(!InstallationFolders.Inspect(Path.Combine(s.patches_dir,"!Chronicles-TexturePatch(4.0.0)")).Valid,"Nested package accepted");});
 Test("nearby-sibling-and-repeated-epsilon-candidates-detected-read-only",delegate{var s=Seed();var main=Directory.GetParent(Directory.GetParent(s.patches_dir).FullName).FullName;var nested=Path.Combine(main,"Epsilon","_retail_","Patches");Directory.CreateDirectory(nested);var other=Path.Combine(Path.GetDirectoryName(main),"OtherInstall","_retail_","Patches");Directory.CreateDirectory(other);var x=InstallationFolders.Inspect(s.patches_dir);Assert(x.Nearby.Contains(nested)&&x.Nearby.Contains(other),"Duplicates omitted");Assert(Directory.GetFiles(main,"*",SearchOption.AllDirectories).Length==3,"Inspection changed files");});
 Test("every-fifth-update-count-persists-and-stays-due-until-confirmed",delegate{var s=Seed();for(int i=0;i<4;i++)Assert(!s.CountFolderCheck(),"Prompt too early");s.Save();s=State.Load();Assert(s.folder_check_uses==4&&s.CountFolderCheck()&&s.CountFolderCheck(),"Schedule lost or skipped");});
 Test("yes-cannot-bypass-invalid-layout",delegate{var s=Seed(false);using(var f=new MainForm(new LauncherFixtureSource(),null,true)){f.ConfirmInstallation=x=>DialogResult.Yes;Assert(!f.CheckInstallationFolders(),"Invalid root confirmed");}});
 Test("no-selects-again-and-confirmed-correct-folder-resets-counter",delegate{var s=Seed();s.folder_check_uses=4;s.Save();var second=Path.Combine(Path.GetDirectoryName(Directory.GetParent(Directory.GetParent(s.patches_dir).FullName).FullName),"Correct","_retail_","Patches");string secondMain=Directory.GetParent(Directory.GetParent(second).FullName).FullName;Directory.CreateDirectory(second);Directory.CreateDirectory(Path.Combine(secondMain,"Data"));File.WriteAllText(Path.Combine(secondMain,"Epsilon.exe"),"fixture");File.WriteAllText(Path.Combine(Path.GetDirectoryName(second),"Wow.exe"),"fixture");File.WriteAllText(Path.Combine(Path.GetDirectoryName(second),"EpsilonAddon.dll"),"fixture");using(var f=new MainForm(new LauncherFixtureSource(),null,true)){int prompts=0;f.ConfirmInstallation=x=>++prompts==1?DialogResult.Retry:DialogResult.Yes;f.SelectFolderForCheck=()=>{typeof(MainForm).GetMethod("RememberFolder",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{second});return true;};Assert(f.CheckInstallationFolders()&&prompts==2&&State.Load().patches_dir==second&&State.Load().folder_check_uses==0,"Reselection failed");}});
 Test("cancel-does-not-change-selected-folder-or-game-files",delegate{var s=Seed();var before=Directory.GetFiles(Path.GetDirectoryName(s.patches_dir),"*",SearchOption.AllDirectories);using(var f=new MainForm(new LauncherFixtureSource(),null,true)){f.ConfirmInstallation=x=>DialogResult.Cancel;Assert(!f.CheckInstallationFolders(),"Cancel ignored");}Assert(State.Load().patches_dir==s.patches_dir&&before.SequenceEqual(Directory.GetFiles(Path.GetDirectoryName(s.patches_dir),"*",SearchOption.AllDirectories)),"Cancel changed game");});
 Test("fifth-actual-update-runs-confirmation-but-first-four-do-not",delegate{var s=Seed();var src=new LauncherFixtureSource();src.Publish("fixture");using(var f=new MainForm(src,null,true)){f.Show();int confirmations=0,choices=0;f.ConfirmInstallation=x=>{confirmations++;return DialogResult.Yes;};f.ChoosePatches=p=>{choices++;return null;};for(int i=1;i<=5;i++){Check(f);int expected=i;Pump(()=>choices==expected&&!(bool)Field(f,"isBusy"));Assert(confirmations==(i==5?1:0),"Wrong periodic cadence");}Assert(src.Downloads.Count==0&&State.Load().folder_check_uses==0,"Periodic check installed assets");f.Close();}});
 Test("troubleshooting-action-runs-immediately-without-waiting-five",delegate{var s=Seed();var src=new LauncherFixtureSource();src.Publish("fixture");using(var f=new MainForm(src,null,true)){f.Show();int confirmations=0,choices=0;f.ConfirmInstallation=x=>{confirmations++;return DialogResult.Yes;};f.ChoosePatches=p=>++choices==1?new PatchSelection{CheckFolders=true}:null;Check(f);Pump(()=>choices==2&&!(bool)Field(f,"isBusy"));Assert(confirmations==1&&src.Downloads.Count==0&&State.Load().folder_check_uses==0,"Manual action failed");f.Close();}});
 Test("invalid-fifth-update-stops-before-catalog-or-download",delegate{var s=Seed(false);s.folder_check_uses=4;s.Save();var src=new LauncherFixtureSource();src.Publish("fixture");using(var f=new MainForm(src,null,true)){f.ConfirmInstallation=x=>DialogResult.Cancel;Check(f);Assert(src.Reads==0&&src.Downloads.Count==0&&State.Load().folder_check_uses==5,"Invalid update continued");}});
 Test("themed-confirmation-displays-path-and-disabled-yes-for-invalid-root",delegate{var s=Seed(false);using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=delegate{var f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text.StartsWith("Check installation folders"));if(f==null)return;timer.Stop();Assert(f.Controls.OfType<TextBox>().Single().Text.Contains(s.patches_dir),"Exact path missing");Assert(!f.Controls.OfType<Button>().Single(x=>x.Text=="Yes, this is correct").Enabled,"Invalid yes enabled");using(var image=new System.Drawing.Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new System.Drawing.Rectangle(System.Drawing.Point.Empty,image.Size));image.Save(Path.Combine(root,"folder-confirmation.png"));}f.Controls.OfType<Button>().Single(x=>x.Text=="No, select folder").PerformClick();};timer.Start();Assert(PatchDialogs.Installation(null,InstallationFolders.Inspect(s.patches_dir))==DialogResult.Retry,"No result incorrect");}});
 Test("changelog-dialog-and-bottom-left-gear-are-present",delegate{var s=Seed();using(var f=new MainForm(new LauncherFixtureSource(),null,true)){Assert(f.Controls.OfType<Button>().Any(x=>x.AccessibleName=="Open updater changelog"),"Gear missing");}using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=delegate{var f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text.StartsWith("Updater changelog"));if(f==null)return;timer.Stop();var text=f.Controls.OfType<TextBox>().Single().Text;Assert(text.Contains("1.5.6")&&text.Contains("1.5.5")&&text.Contains("1.5.2"),"Release history incomplete");f.Controls.OfType<Button>().Single().PerformClick();};timer.Start();PatchDialogs.Changelog(null);}});
 Console.WriteLine("TOTAL "+passed+" installation/schedule/UI cases passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
